  return [pts[0], pts[1]];
}

function addInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

draw.rect(W, H).fill('#ffffff');

var clipA = draw.clip().add(draw.rect(panelA.w, panelA.h).move(panelA.x, panelA.y));
var heat = draw.group().clipWith(clipA);

var minL = Infinity, maxL = -Infinity;
var samples = [];
for (var gy = 0; gy < 64; gy++) {
  for (var gx = 0; gx < 64; gx++) {
    var p0 = panelA.p0min + (gx + 0.5) / 64 * (panelA.p0max - panelA.p0min);
    var p1 = panelA.p1min + (gy + 0.5) / 64 * (panelA.p1max - panelA.p1min);
    var l = loss(p0, p1);
    samples.push([gx, gy, l]);
    minL = Math.min(minL, l);
    maxL = Math.max(maxL, l);
  }
}
for (var si = 0; si < samples.length; si++) {
  var item = samples[si];
  var norm = Math.pow((item[2] - minL) / (maxL - minL), 0.72);
  heat.rect(panelA.w / 64 + 0.8, panelA.h / 64 + 0.8)
    .move(panelA.x + item[0] * panelA.w / 64, panelA.y + item[1] * panelA.h / 64)
    .fill(mixColor('#f5c7a2', '#330905', norm));
}

var contours = draw.group().clipWith(clipA);
function contourPath(r) {
  var cx = 0.80, cy = 0.52, theta = -0.62;
  var cu = Math.cos(theta), su = Math.sin(theta);
  var rx = r * 1.35, ry = r * 0.34;
  var pts = [];
  for (var i = 0; i <= 220; i++) {
    var a = i / 220 * Math.PI * 2;
    var u = rx * Math.cos(a), v = ry * Math.sin(a);
    var dx = cu * u - su * v;
    var dy = su * u + cu * v;
    pts.push([Ax(cx + dx), Ay(cy + dy)]);
  }
  return pts.map(function (p, i) { return (i ? 'L' : 'M') + p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ');
}
for (var cr = 0.23; cr < 1.98; cr += 0.18) {
  contours.path(contourPath(cr)).fill('none').stroke({ color: '#7d7775', width: 2.2, opacity: 0.72 });
}
addInteractive(heat.rect(panelA.w, panelA.h).move(panelA.x, panelA.y).fill({ color: '#fff', opacity: 0 }),
  'Loss landscape: every pixel is a different intercept–slope pair.',
  'Loss landscape',
  'Panel a is parameter space. Moving across it changes both the model parameters and the training loss computed from the orange observations.');

draw.rect(panelA.w, panelA.h).move(panelA.x, panelA.y).fill('none').stroke({ color: '#000', width: 3 });
draw.rect(panelB.w, panelB.h).move(panelB.x, panelB.y).fill('none').stroke({ color: '#000', width: 3 });

function tickA() {
  for (var i = 0; i <= 10; i++) {
    var tx = panelA.x + i / 10 * panelA.w;
    draw.line(tx, panelA.y + panelA.h, tx, panelA.y + panelA.h + (i % 5 === 0 ? 13 : 7)).stroke({ color: '#777', width: 3 });
    var ty = panelA.y + i / 10 * panelA.h;
    draw.line(panelA.x - (i % 5 === 0 ? 13 : 7), ty, panelA.x, ty).stroke({ color: '#777', width: 3 });
  }
  [['0.0', 0], ['1.0', 1], ['2.0', 2]].forEach(function (t) {
    draw.text(t[0]).font({ family: 'sans-serif', size: 24, anchor: 'middle' }).fill('#808080')
      .center(Ax(t[1]), panelA.y + panelA.h + 27);
  });
  [['-1.0', -1], ['0.0', 0], ['1.0', 1]].forEach(function (t) {
    draw.text(t[0]).font({ family: 'sans-serif', size: 24, anchor: 'end' }).fill('#808080')
      .center(panelA.x - 34, Ay(t[1]));
  });
}
function tickB() {
  for (var i = 0; i <= 10; i++) {
    var tx = panelB.x + i / 10 * panelB.w;
    draw.line(tx, panelB.y + panelB.h, tx, panelB.y + panelB.h + (i % 5 === 0 ? 13 : 7)).stroke({ color: '#777', width: 3 });
    var ty = panelB.y + panelB.h - i / 10 * panelB.h;
    draw.line(panelB.x - (i % 5 === 0 ? 13 : 7), ty, panelB.x, ty).stroke({ color: '#777', width: 3 });
  }
  [['0.0', 0], ['1.0', 1], ['2.0', 2]].forEach(function (t) {
    draw.text(t[0]).font({ family: 'sans-serif', size: 24, anchor: 'middle' }).fill('#808080')
      .center(Bx(t[1]), panelB.y + panelB.h + 27);
    draw.text(t[0]).font({ family: 'sans-serif', size: 24, anchor: 'end' }).fill('#808080')
      .center(panelB.x - 32, By(t[1]));
  });
}
tickA();
tickB();

draw.text('a)').font({ family: 'sans-serif', size: 34, anchor: 'middle' }).fill('#000').center(18, 24);
draw.text('b)').font({ family: 'sans-serif', size: 34, anchor: 'middle' }).fill('#000').center(584, 24);
draw.text('Loss, L[ϕ]').font({ family: 'sans-serif', size: 32, anchor: 'middle' }).fill('#000').center(panelA.x + panelA.w / 2, 28);
draw.text('Intercept, ϕ₀').font({ family: 'sans-serif', size: 30, anchor: 'middle' }).fill('#000').center(panelA.x + panelA.w / 2, 546);
draw.text('Slope, ϕ₁').font({ family: 'sans-serif', size: 30, anchor: 'middle' }).fill('#000').center(27, panelA.y + panelA.h / 2).rotate(-90, 27, panelA.y + panelA.h / 2);
draw.text('Input, x').font({ family: 'sans-serif', size: 30, anchor: 'middle' }).fill('#000').center(panelB.x + panelB.w / 2, 546);
draw.text('Output, y').font({ family: 'sans-serif', size: 30, anchor: 'middle' }).fill('#000').center(593, panelB.y + panelB.h / 2).rotate(-90, 593, panelB.y + panelB.h / 2);

var pathGroup = draw.group();
var pathPts = pathStates.map(function (p) { return [Ax(p.phi0), Ay(p.phi1)]; });
pathGroup.polyline(pathPts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
  .fill('none').stroke({ color: '#bfbfbf', width: 5, linecap: 'round', linejoin: 'round', opacity: 0.92 });
for (var pi = 0; pi < pathStates.length; pi++) {
  (function (idx) {
    var p = pathStates[idx];
    var c = pathGroup.circle(idx === 4 ? 19 : 18).center(Ax(p.phi0), Ay(p.phi1))
      .fill(idx === 4 ? '#2c8581' : '#bce4df').stroke('none');
    addInteractive(c, 'Stored parameter state ' + idx + ': ϕ₀=' + p.phi0.toFixed(2) + ', ϕ₁=' + p.phi1.toFixed(2),
      'Parameter state ' + idx,
      'This point in panel a corresponds to one straight line in panel b. Lower-loss states are closer to the pale basin and fit the data trend better.');
    pathGroup.text(String(idx)).font({ family: 'sans-serif', size: 24, anchor: 'middle' }).fill('#fff')
      .attr({ 'paint-order': 'stroke', stroke: '#3d0b07', 'stroke-width': 2.8, 'stroke-linejoin': 'round' })
      .center(Ax(p.phi0), Ay(p.phi1) + 31);
  })(pi);
}

var dataGroup = draw.group();
for (var di = 0; di < data.length; di++) {
  var dot = dataGroup.circle(21).center(Bx(data[di][0]), By(data[di][1]))
    .fill('#d27d58').stroke({ color: '#7d3a24', width: 2 });
  addInteractive(dot, 'Training observation: x=' + data[di][0].toFixed(2) + ', y=' + data[di][1].toFixed(2),
    'Supervised training point',
    'The loss compares each orange observed output with the model prediction at the same input. A better line has smaller residuals to these points overall.');
}

var lineColors = ['#bfe8e5', '#98d9d2', '#79cbc4', '#49b8b1', '#2b7b73'];
var lineGroup = draw.group();
function drawLineFor(group, phi0, phi1, color, width, opacity) {
  var seg = lineSegmentInBox(phi0, phi1);
  if (!seg) return null;
  return group.line(Bx(seg[0][0]), By(seg[0][1]), Bx(seg[1][0]), By(seg[1][1]))
    .stroke({ color: color, width: width, opacity: opacity, linecap: 'round' });
}
for (var li = 0; li < pathStates.length; li++) {
  var ln = drawLineFor(lineGroup, pathStates[li].phi0, pathStates[li].phi1, lineColors[li], li === 4 ? 5.5 : 5, 1);
  if (ln) {
    addInteractive(ln, 'Fitted line for stored parameter state ' + li,
      'Line ' + li,
      'This line is y = ϕ₀ + ϕ₁x using parameter state ' + li + ' from the path in panel a.');
  }
  var lx = li === 0 ? 0.28 : 0.10 + li * 0.03;
  var ly = pathStates[li].phi0 + pathStates[li].phi1 * lx;
  lineGroup.text(String(li)).font({ family: 'sans-serif', size: 25, anchor: 'middle' }).fill(lineColors[li])
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' })
    .center(Bx(lx), By(ly) + (li === 0 ? 12 : -5));
}

var dynamicGroup = draw.group();
var currentLine = null;
var currentMarker = draw.circle(23).fill('#85d7d2').stroke({ color: '#155f5a', width: 2.5 });
currentMarker.front();
currentMarker.css('cursor', 'grab');
currentMarker.on('mousemove', function (e) { showTooltip('Drag to choose intercept ϕ₀ and slope ϕ₁. The line in panel b updates immediately.', e); });
currentMarker.on('mouseleave', function () { hideTooltip(); });
currentMarker.on('click', function () {
  showPopup('One parameter point, one model line',
    'The horizontal coordinate is the intercept ϕ₀ and the vertical coordinate is the slope ϕ₁. Together they define the single fitted line y = ϕ₀ + ϕ₁x shown in panel b.');
});

var dragging = false;
currentMarker.on('mousedown', function (e) {
  dragging = true;
  currentMarker.css('cursor', 'grabbing');
  e.preventDefault();
});
document.addEventListener('mousemove', function (e) {
  if (!dragging) return;
  var pt = draw.node.createSVGPoint();
  pt.x = e.clientX; pt.y = e.clientY;
  var loc = pt.matrixTransform(draw.node.getScreenCTM().inverse());
  var p0 = clamp(Aphi0(loc.x), panelA.p0min, panelA.p0max);
  var p1 = clamp(Aphi1(loc.y), Math.max(panelA.p1min, 0), panelA.p1max);
  setParameters(p0, p1, true);
});
document.addEventListener('mouseup', function () {
  if (dragging) {
    dragging = false;
    currentMarker.css('cursor', 'grab');
  }
});

function setSlider(id, v) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = String(v);
  if (out) out.value = Number(v).toFixed(2).replace(/\.?0+$/, function (m) { return m === '.00' ? '' : m; });
}

function setParameters(phi0, phi1, fromDrag) {
  state.phi0 = clamp(phi0, -1, 2);
  state.phi1 = clamp(phi1, 0, 4);
  if (fromDrag) {
    setSlider('interceptPhi0', state.phi0);
    setSlider('slopePhi1', state.phi1);
  }
  updateVisuals();
}

function updateVisuals() {
  var shownPhi0 = clamp(state.phi0, panelA.p0min, panelA.p0max);
  var shownPhi1 = clamp(state.phi1, panelA.p1min, panelA.p1max);
  currentMarker.center(Ax(shownPhi0), Ay(shownPhi1)).front();

  dynamicGroup.clear();
  var seg = lineSegmentInBox(state.phi0, state.phi1);
  if (seg) {
    currentLine = dynamicGroup.line(Bx(seg[0][0]), By(seg[0][1]), Bx(seg[1][0]), By(seg[1][1]))
      .stroke({ color: '#145f59', width: 7.5, opacity: 0.96, linecap: 'round' });
    currentLine.back();
    lineGroup.front();
    dataGroup.front();
    currentMarker.front();
    addInteractive(currentLine, 'Current fitted line: y = ' + state.phi0.toFixed(2) + ' + ' + state.phi1.toFixed(2) + 'x',
      'Current fitted line',
      'Changing ϕ₀ shifts this line, and changing ϕ₁ rotates it. The loss is the average squared prediction error over the orange data.');
  }
  var L = loss(state.phi0, state.phi1);
  var readout = document.getElementById('lossReadout');
  if (readout) readout.textContent = 'Loss L[ϕ] = ' + L.toFixed(3) + ' for y = ' + state.phi0.toFixed(2) + ' + ' + state.phi1.toFixed(2) + 'x';
}

function update_interceptPhi0(v) {
  state.phi0 = v;
  updateVisuals();
}
function update_slopePhi1(v) {
  state.phi1 = v;
  updateVisuals();
}

function applyStep(i) {
  currentStep = clamp(i, 0, demoSteps.length - 1);
  var st = demoSteps[currentStep];
  var p0 = st.state.interceptPhi0;
  var p1 = st.state.slopePhi1;
  setSlider('interceptPhi0', p0);
  setSlider('slopePhi1', p1);
  setParameters(p0, p1, false);
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = st.title + ': ' + st.narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length;
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }
function trigger_parameterPoint() {}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A linear model's supervised loss is a landscape over intercept and slope, where each parameter point corresponds to one fitted line in data space and lower-loss points produce better fits.
KEY INSIGHT (what students should walk away understanding): Training a supervised linear model means moving a point on the parameter-space loss landscape until the corresponding line in data space fits the observations well.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A linear model's supervised loss is a landscape over intercept and slope, where each parameter point corresponds to one fitted line in data space and lower-loss points produce better fits.",
  "figureType": "other",
  "elements": [
    "panel label 'a)' for the loss landscape",
    "panel a title 'Loss, L[ϕ]'",
    "panel a x-axis labeled 'Intercept, ϕ0' with tick marks spanning roughly 0 to 2",
    "panel a y-axis labeled 'Slope, ϕ1' with tick marks spanning the displayed slope range",
    "panel a colored loss heatmap with darkest/highest loss toward the outer regions and lightest/lower loss near the minimum valley",
    "panel a nested contour lines showing equal-loss curves",
    "panel a current parameter marker on the loss surface",
    "panel a optimization path drawn as a gray polyline through parameter points",
    "panel a numbered parameter markers 0, 1, 2, 3, and 4 along the path",
    "panel label 'b)' for the data-space view",
    "panel b x-axis labeled 'Input, x' with ticks at 0, 1, and 2",
    "panel b y-axis labeled 'Output, y' with ticks at 0, 1, and 2",
    "panel b orange circular supervised training data points",
    "panel b family of fitted straight lines corresponding to parameter states 0, 1, 2, 3, and 4",
    "panel b teal line labels 0, 1, 2, 3, and 4 near the left side of the corresponding fitted lines",
    "panel b highlighted current fitted line y = ϕ0 + ϕ1x"
  ],
  "interactions": [
    {
      "id": "parameterPoint",
      "type": "drag",
      "teaches": "A single location on the loss surface fixes both model parameters, so dragging the point immediately changes the line fitted through the data and reveals whether that choice has high or low training loss"
    },
    {
      "id": "interceptPhi0",
      "type": "slider",
      "label": "Intercept, ϕ0",
      "range": [
        -1,
        2,
        0.01
      ],
      "default": 0.8,
      "teaches": "Changing the intercept shifts the fitted line up or down while moving the parameter point along the intercept direction of the loss landscape"
    },
    {
      "id": "slopePhi1",
      "type": "slider",
      "label": "Slope, ϕ1",
      "range": [
        0,
        4,
        0.01
      ],
      "default": 0.55,
      "teaches": "Changing the slope rotates the fitted line and moves the parameter point through a different direction of the same loss landscape"
    }
  ],
  "demo_steps": [
    {
      "title": "One point, one line",
      "narration": "The marker in panel a is one parameter setting, ϕ = (ϕ0, ϕ1). The line in panel b is the linear model produced by exactly that intercept and slope.",
      "state": {
        "interceptPhi0": 0.15,
        "slopePhi1": 0.1
      }
    },
    {
      "title": "Adjust the intercept",
      "narration": "Move the intercept slider: the fitted line shifts upward or downward without changing its tilt much. On the loss surface, the same change moves the parameter point across contours and changes the loss.",
      "state": {
        "interceptPhi0": 0.55,
        "slopePhi1": 0.1
      }
    },
    {
      "title": "Adjust the slope",
      "narration": "Now move the slope slider: the fitted line rotates to better match the trend of the orange data points. The marker moves toward lower contours when the line better matches the data.",
      "state": {
        "interceptPhi0": 0.55,
        "slopePhi1": 0.45
      }
    },
    {
      "title": "Near the minimum",
      "narration": "At a low-loss point, the fitted line passes through the middle of the data cloud and the marker sits near the lightest part of the contour map. Optimization is the process of moving through parameter space toward this region.",
      "state": {
        "interceptPhi0": 0.8,
        "slopePhi1": 0.55
      }
    }
  ],
  "keyInsight": "Training a supervised linear model means moving a point on the parameter-space loss landscape until the corresponding line in data space fits the observations well.",
  "reconstructionNotes": "Use a two-panel horizontal layout. Panel a should be a square-ish contour heatmap of L[ϕ] with intercept on the horizontal axis and slope on the vertical axis; draw nested smooth contour curves and a pale low-loss basin near the path endpoint. Overlay a gray optimization path with cyan parameter markers labeled 0 through 4. Panel b should show orange training-data dots with dark outlines and several fitted lines in progressively darker teal, labeled 0 through 4 near their left ends; the darkest line should correspond to the lowest-loss/most recent parameter point. Keep both panels visually linked: changing or dragging the parameter marker updates the highlighted line and the numeric parameter labels consistently."
}

