var demoSteps = [
  {
    title: 'One point, one line',
    narration: 'The marker in panel a is one parameter setting, ϕ = (ϕ0, ϕ1). The line in panel b is the linear model produced by exactly that intercept and slope.',
    state: { interceptPhi0: 0.15, slopePhi1: 0.10 }
