var currentStep = 3;

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function Ax(phi0) { return panelA.x + (phi0 - panelA.p0min) / (panelA.p0max - panelA.p0min) * panelA.w; }
function Ay(phi1) { return panelA.y + (phi1 - panelA.p1min) / (panelA.p1max - panelA.p1min) * panelA.h; }
function Aphi0(sx) { return panelA.p0min + (sx - panelA.x) / panelA.w * (panelA.p0max - panelA.p0min); }
function Aphi1(sy) { return panelA.p1min + (sy - panelA.y) / panelA.h * (panelA.p1max - panelA.p1min); }
function Bx(x) { return panelB.x + (x - panelB.xmin) / (panelB.xmax - panelB.xmin) * panelB.w; }
function By(y) { return panelB.y + panelB.h - (y - panelB.ymin) / (panelB.ymax - panelB.ymin) * panelB.h; }

function mixColor(c1, c2, t) {
  t = clamp(t, 0, 1);
  function h(c, i) { return parseInt(c.slice(1 + 2 * i, 3 + 2 * i), 16); }
  var r = Math.round(h(c1, 0) + (h(c2, 0) - h(c1, 0)) * t);
  var g = Math.round(h(c1, 1) + (h(c2, 1) - h(c1, 1)) * t);
  var b = Math.round(h(c1, 2) + (h(c2, 2) - h(c1, 2)) * t);
