  return mixColor('#9a5140', '#f0b78f', (t - 0.78) / 0.22);
}

function loss(phi0, phi1) {
  var s = 0;
  for (var i = 0; i < data.length; i++) {
    var e = phi0 + phi1 * data[i][0] - data[i][1];
    s += e * e;
  }
  return s / data.length;
}

function addInteractive(el, tip, title, body) {
