  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

draw.rect(W, H).fill('#ffffff');

var clipA = draw.clip().add(draw.rect(panelA.w, panelA.h).move(panelA.x, panelA.y));
var heatGroup = draw.group().clipWith(clipA);

var minL = Infinity, maxL = -Infinity;
for (var cy0 = 0; cy0 <= 90; cy0++) {
  for (var cx0 = 0; cx0 <= 90; cx0++) {
    var pp0 = panelA.p0min + cx0 / 90 * (panelA.p0max - panelA.p0min);
    var pp1 = panelA.p1min + cy0 / 90 * (panelA.p1max - panelA.p1min);
    var lv = loss(pp0, pp1);
    minL = Math.min(minL, lv);
    maxL = Math.max(maxL, lv);
  }
}

var canvas = document.createElement('canvas');
canvas.width = 560;
canvas.height = 560;
var ctx = canvas.getContext('2d');
var img = ctx.createImageData(canvas.width, canvas.height);
for (var yy = 0; yy < canvas.height; yy++) {
  for (var xx = 0; xx < canvas.width; xx++) {
    var p0 = panelA.p0min + xx / (canvas.width - 1) * (panelA.p0max - panelA.p0min);
    var p1 = panelA.p1min + yy / (canvas.height - 1) * (panelA.p1max - panelA.p1min);
    var n = Math.pow((loss(p0, p1) - minL) / (maxL - minL), 0.62);
    var col = ramp(n);
    var k = (yy * canvas.width + xx) * 4;
    img.data[k] = parseInt(col.slice(1, 3), 16);
    img.data[k + 1] = parseInt(col.slice(3, 5), 16);
    img.data[k + 2] = parseInt(col.slice(5, 7), 16);
    img.data[k + 3] = 255;
  }
}
ctx.putImageData(img, 0, 0);
heatGroup.image(canvas.toDataURL()).move(panelA.x, panelA.y).size(panelA.w, panelA.h);

var contours = draw.group().clipWith(clipA);
var mx = 0, my = 0, mxx = 0, mxy = 0;
for (var i = 0; i < data.length; i++) {
  mx += data[i][0];
  my += data[i][1];
  mxx += data[i][0] * data[i][0];
  mxy += data[i][0] * data[i][1];
}
mx /= data.length; my /= data.length; mxx /= data.length; mxy /= data.length;
var det = mxx - mx * mx;
var opt0 = (mxx * my - mx * mxy) / det;
var opt1 = (mxy - mx * my) / det;
var qa = 1, qb = mx, qc = mxx;
var tr = qa + qc;
var disc = Math.sqrt((qa - qc) * (qa - qc) + 4 * qb * qb);
var lam1 = (tr + disc) / 2, lam2 = (tr - disc) / 2;
var ang = Math.atan2(lam1 - qa, qb || 1e-9);
var co = Math.cos(ang), si = Math.sin(ang);
var maxD = 0;
[[0, -1], [2, -1], [0, 1], [2, 1]].forEach(function (q) {
  maxD = Math.max(maxD, loss(q[0], q[1]) - loss(opt0, opt1));
});
function contourPath(d) {
  var r1 = Math.sqrt(d / lam1);
  var r2 = Math.sqrt(d / lam2);
  var pts = [];
  for (var j = 0; j <= 280; j++) {
    var t = j / 280 * Math.PI * 2;
    var u = r1 * Math.cos(t), v = r2 * Math.sin(t);
    var dx = co * u - si * v;
    var dy = si * u + co * v;
    pts.push([Ax(opt0 + dx), Ay(opt1 + dy)]);
  }
  return pts.map(function (p, j) { return (j ? 'L' : 'M') + p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ');
}
for (var ci = 1; ci <= 29; ci++) {
  var d = maxD * Math.pow(ci / 30, 1.58);
  contours.path(contourPath(d)).fill('none')
    .stroke({ color: '#8b807d', width: 2.25, opacity: 0.62, linecap: 'round', linejoin: 'round' });
}
addInteractive(draw.rect(panelA.w, panelA.h).move(panelA.x, panelA.y).fill({ color: '#fff', opacity: 0 }),
  'Each location is one intercept–slope pair; color and contours show its supervised loss.',
  'Loss landscape',
  'Panel a is parameter space. Moving the point changes the line in panel b and changes the average squared error to the orange observations.');

function drawFrame(p) {
