}
drawFrame(panelA);
drawFrame(panelB);

function ticksA() {
  for (var i = 0; i <= 10; i++) {
    var tx = panelA.x + i / 10 * panelA.w;
    var ty = panelA.y + i / 10 * panelA.h;
    draw.line(tx, panelA.y + panelA.h, tx, panelA.y + panelA.h + (i % 5 === 0 ? 15 : 8)).stroke({ color: '#777777', width: 3 });
    draw.line(panelA.x - (i % 5 === 0 ? 15 : 8), ty, panelA.x, ty).stroke({ color: '#777777', width: 3 });
  }
  [['0.0', 0], ['1.0', 1], ['2.0', 2]].forEach(function (t) {
    draw.text(t[0]).font({ family: 'sans-serif', size: 28, anchor: 'middle' }).fill('#777777').center(Ax(t[1]), panelA.y + panelA.h + 31);
  });
  [['-1.0', -1], ['0.0', 0], ['1.0', 1]].forEach(function (t) {
    draw.text(t[0]).font({ family: 'sans-serif', size: 28, anchor: 'end' }).fill('#777777').center(panelA.x - 37, Ay(t[1]));
  });
}
function ticksB() {
  for (var i = 0; i <= 10; i++) {
    var tx = panelB.x + i / 10 * panelB.w;
    var ty = panelB.y + panelB.h - i / 10 * panelB.h;
    draw.line(tx, panelB.y + panelB.h, tx, panelB.y + panelB.h + (i % 5 === 0 ? 15 : 8)).stroke({ color: '#777777', width: 3 });
    draw.line(panelB.x - (i % 5 === 0 ? 15 : 8), ty, panelB.x, ty).stroke({ color: '#777777', width: 3 });
  }
  [['0.0', 0], ['1.0', 1], ['2.0', 2]].forEach(function (t) {
    draw.text(t[0]).font({ family: 'sans-serif', size: 28, anchor: 'middle' }).fill('#777777').center(Bx(t[1]), panelB.y + panelB.h + 31);
    draw.text(t[0]).font({ family: 'sans-serif', size: 28, anchor: 'end' }).fill('#777777').center(panelB.x - 37, By(t[1]));
  });
}
ticksA();
ticksB();

draw.text('a)').font({ family: 'sans-serif', size: 38, anchor: 'middle' }).fill('#000000').center(18, 25);
draw.text('b)').font({ family: 'sans-serif', size: 38, anchor: 'middle' }).fill('#000000').center(780, 25);
draw.text('Loss, L[ϕ]').font({ family: 'sans-serif', size: 42, anchor: 'middle' }).fill('#000000').center(panelA.x + panelA.w / 2, 31);
draw.text('Intercept, ϕ₀').font({ family: 'sans-serif', size: 40, anchor: 'middle' }).fill('#000000').center(panelA.x + panelA.w / 2, 776);
draw.text('Slope, ϕ₁').font({ family: 'sans-serif', size: 40, anchor: 'middle' }).fill('#000000').center(30, panelA.y + panelA.h / 2).rotate(-90, 30, panelA.y + panelA.h / 2);
draw.text('Input, x').font({ family: 'sans-serif', size: 40, anchor: 'middle' }).fill('#000000').center(panelB.x + panelB.w / 2, 776);
draw.text('Output, y').font({ family: 'sans-serif', size: 40, anchor: 'middle' }).fill('#000000').center(790, panelB.y + panelB.h / 2).rotate(-90, 790, panelB.y + panelB.h / 2);

var pathGroup = draw.group();
var pathPts = pathStates.map(function (p) { return [Ax(p.phi0), Ay(p.phi1)]; });
pathGroup.polyline(pathPts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
  .fill('none').stroke({ color: '#bcbcbc', width: 6, linecap: 'round', linejoin: 'round', opacity: 0.95 });
for (var pi = 0; pi < pathStates.length; pi++) {
  (function (idx) {
    var p = pathStates[idx];
    var cpt = pathGroup.circle(idx === 4 ? 24 : 23).center(Ax(p.phi0), Ay(p.phi1))
      .fill(idx === 4 ? '#28786f' : '#bfe8e5').stroke('none');
    addInteractive(cpt, 'Parameter state ' + idx + ': ϕ₀=' + p.phi0.toFixed(2) + ', ϕ₁=' + p.phi1.toFixed(2),
      'Parameter state ' + idx,
      'This point corresponds to one fitted line in panel b. The path shows a move through parameter space toward lower supervised loss.');
    pathGroup.text(String(idx)).font({ family: 'sans-serif', size: 30, anchor: 'middle' }).fill('#ffffff')
      .attr({ 'paint-order': 'stroke', stroke: '#3b0b07', 'stroke-width': 3.5, 'stroke-linejoin': 'round' })
      .center(Ax(p.phi0), Ay(p.phi1) + 38);
  })(pi);
}

function lineSegmentInBox(phi0, phi1) {
  var pts = [];
  function add(x, y) {
    if (x >= panelB.xmin - 1e-9 && x <= panelB.xmax + 1e-9 && y >= panelB.ymin - 1e-9 && y <= panelB.ymax + 1e-9) {
      for (var j = 0; j < pts.length; j++) {
        if (Math.abs(pts[j][0] - x) < 1e-7 && Math.abs(pts[j][1] - y) < 1e-7) return;
      }
      pts.push([x, y]);
    }
  }
  add(panelB.xmin, phi0 + phi1 * panelB.xmin);
  add(panelB.xmax, phi0 + phi1 * panelB.xmax);
  if (Math.abs(phi1) > 1e-9) {
    add((panelB.ymin - phi0) / phi1, panelB.ymin);
    add((panelB.ymax - phi0) / phi1, panelB.ymax);
  }
  if (pts.length < 2) return null;
  pts.sort(function (a, b) { return a[0] - b[0]; });
  return [pts[0], pts[pts.length - 1]];
}
function drawLineFor(group, phi0, phi1, color, width, opacity) {
  var seg = lineSegmentInBox(phi0, phi1);
  if (!seg) return null;
  return group.line(Bx(seg[0][0]), By(seg[0][1]), Bx(seg[1][0]), By(seg[1][1]))
    .stroke({ color: color, width: width, opacity: opacity, linecap: 'round' });
}

var lineGroup = draw.group();
var lineColors = ['#bfe8e5', '#9bd9d3', '#7fc9c1', '#4cb7ae', '#28786f'];
var labelXs = [0.28, 0.22, 0.18, 0.14, 0.07];
var labelPath = [];
for (var li = 0; li < pathStates.length; li++) {
  labelPath.push([Bx(labelXs[li]), By(pathStates[li].phi0 + pathStates[li].phi1 * labelXs[li])]);
}
lineGroup.polyline(labelPath.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
  .fill('none').stroke({ color: '#c7c7c7', width: 6, opacity: 0.95, linecap: 'round', linejoin: 'round' });
for (var li2 = 0; li2 < pathStates.length; li2++) {
  var ln = drawLineFor(lineGroup, pathStates[li2].phi0, pathStates[li2].phi1, lineColors[li2], li2 === 4 ? 6.5 : 5.6, 1);
  if (ln) {
    addInteractive(ln, 'Fitted line for state ' + li2 + ': y = ' + pathStates[li2].phi0.toFixed(2) + ' + ' + pathStates[li2].phi1.toFixed(2) + 'x',
