  var yOff = [34, 23, 13, 3, -8][li3];
  lineGroup.text(String(li3)).font({ family: 'sans-serif', size: 34, anchor: 'middle' }).fill(lineColors[li3])
    .attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' })
    .center(Bx(lx) - (li3 === 4 ? 0 : 2), By(ly) + yOff);
}

var dynamicGroup = draw.group();
var dataGroup = draw.group();
for (var di = 0; di < data.length; di++) {
