  var seg = lineSegmentInBox(state.phi0, state.phi1);
  if (seg) {
    var currentLine = dynamicGroup.line(Bx(seg[0][0]), By(seg[0][1]), Bx(seg[1][0]), By(seg[1][1]))
      .stroke({ color: '#236f68', width: 8, opacity: 0.96, linecap: 'round' });
    addInteractive(currentLine, 'Current line: y = ' + fmt(state.phi0) + ' + ' + fmt(state.phi1) + 'x',
